import json

class RestAPI:
    def __init__(self, database=None):
        # Internal storage: map user name -> user dict with keys: name, owes, owed_by, balance
        self.users = {}
        if isinstance(database, str):
            try:
                database = json.loads(database)
            except Exception:
                database = None
        if database and "users" in database:
            for u in database["users"]:
                name = u.get("name")
                owes = dict(u.get("owes", {}))
                owed_by = dict(u.get("owed_by", {}))
                # Ensure float values
                owes = {k: float(v) for k, v in owes.items()}
                owed_by = {k: float(v) for k, v in owed_by.items()}
                self.users[name] = {
                    "name": name,
                    "owes": owes,
                    "owed_by": owed_by,
                    "balance": round(sum(owed_by.values()) - sum(owes.values()), 2),
                }

    def _parse_payload(self, payload):
        if payload is None:
            return None
        if isinstance(payload, str):
            try:
                return json.loads(payload)
            except Exception:
                return None
        return payload

    def _user_dict(self, name):
        # Return a JSON-serializable copy of the user object with rounded amounts
        u = self.users[name]
        owes = {k: round(v, 2) for k, v in u["owes"].items() if round(v, 2) != 0}
        owed_by = {k: round(v, 2) for k, v in u["owed_by"].items() if round(v, 2) != 0}
        balance = round(sum(owed_by.values()) - sum(owes.values()), 2)
        return {"name": name, "owes": owes, "owed_by": owed_by, "balance": balance}

    def _ensure_user(self, name):
        if name not in self.users:
            self.users[name] = {"name": name, "owes": {}, "owed_by": {}, "balance": 0.0}

    def get(self, url, payload=None):
        payload = self._parse_payload(payload)
        if url != "/users":
            return json.dumps({})
        if payload is None or "users" not in payload:
            # Return all users sorted by name
            names = sorted(self.users.keys())
        else:
            # Return only requested users sorted by name
            names = sorted(payload.get("users", []))
        users_list = [self._user_dict(name) for name in names if name in self.users]
        return json.dumps({"users": users_list})

    def post(self, url, payload=None):
        payload = self._parse_payload(payload) or {}
        if url == "/add":
            name = payload.get("user")
            # Create user if not exists
            self._ensure_user(name)
            # Return the new user's object
            return json.dumps(self._user_dict(name))
        elif url == "/iou":
            lender = payload.get("lender")
            borrower = payload.get("borrower")
            amount = float(payload.get("amount", 0))
            # Ensure users exist
            self._ensure_user(lender)
            self._ensure_user(borrower)

            L = self.users[lender]
            B = self.users[borrower]

            # Check if lender currently owes borrower (reverse debt)
            rev_amount = L["owes"].get(borrower, 0.0)
            if rev_amount > 0:
                # There is reverse debt: lender owes borrower rev_amount
                if rev_amount > amount:
                    # Reduce reverse debt
                    new_rev = round(rev_amount - amount, 2)
                    L["owes"][borrower] = new_rev
                    B["owed_by"][lender] = new_rev
                    if new_rev == 0:
                        del L["owes"][borrower]
                        del B["owed_by"][lender]
                elif rev_amount == amount:
                    # Debts cancel out
                    del L["owes"][borrower]
                    del B["owed_by"][lender]
                else:
                    # rev_amount < amount -> borrower ends up owing lender (net)
                    net = round(amount - rev_amount, 2)
                    # Remove reverse entries
                    del L["owes"][borrower]
                    del B["owed_by"][lender]
                    # Add net debt: borrower owes lender
                    B["owes"][lender] = round(B["owes"].get(lender, 0.0) + net, 2)
                    L["owed_by"][borrower] = round(L["owed_by"].get(borrower, 0.0) + net, 2)
            else:
                # No reverse debt, just increase borrower owes lender
                B["owes"][lender] = round(B["owes"].get(lender, 0.0) + amount, 2)
                L["owed_by"][borrower] = round(L["owed_by"].get(borrower, 0.0) + amount, 2)

            # Recalculate balances for both users
            for name in (lender, borrower):
                u = self.users[name]
                # Clean up any zero entries
                u["owes"] = {k: float(round(v, 2)) for k, v in u["owes"].items() if round(v, 2) != 0}
                u["owed_by"] = {k: float(round(v, 2)) for k, v in u["owed_by"].items() if round(v, 2) != 0}
                u["balance"] = round(sum(u["owed_by"].values()) - sum(u["owes"].values()), 2)

            # Return updated user objects for lender and borrower sorted by name
            names = sorted([lender, borrower])
            return json.dumps({"users": [self._user_dict(n) for n in names]})
        else:
            return json.dumps({})
